// Run after esbuild in `npm run build:mcp`: write the MCP bundle into a TS
// module so the server bundle carries it. The daemon loads index.server.ts
// with no plugin directory, so it cannot find mcp/epic-mcp.mjs on disk;
// materializeMcpBundle() writes this string to a temp file instead.
import { readFileSync, writeFileSync } from "node:fs";

const bundle = readFileSync(new URL("../mcp/epic-mcp.mjs", import.meta.url), "utf8");
const out = new URL("../server/mcp/bundle.generated.ts", import.meta.url);
writeFileSync(
  out,
  "// Generated by scripts/gen-mcp-module.mjs from mcp/epic-mcp.mjs. Do not edit; run `npm run build:mcp`.\n" +
    `export const MCP_BUNDLE: string = ${JSON.stringify(bundle)};\n`,
);
